function renderProfile(user) {
    var html = '<div class="profile-card">';
    html += '<h1>' + user.name + '</h1>';
    html += '<p>' + user.bio + '</p>';
    html += '<span class="status">' + user.status_message + '</span>';
    html += '</div>';
    document.getElementById('profile-container').innerHTML = html;
}
